import unittest
from labels import normalize_label

class Labels(unittest.TestCase):
    def test_outer_space(self):
        self.assertEqual(normalize_label("  Hi  "), "hi")
    def test_lowercase(self):
        self.assertEqual(normalize_label("ABC"), "abc")
    def test_internal_spacing(self):
        self.assertEqual(normalize_label("A  B"), "a  b")

if __name__ == "__main__":
    unittest.main()
